import {useState, useEffect} from 'react';
import styles from './styles/AssTicModStyles.module.css';

function AssignTicketModal({closeAssignTicketModal, ticket}){
    const [users, setUsers] = useState([]);

    useEffect(() => {
        async function fetchEmployees(){
            try {
                    const response = await fetch("http://localhost:3001/listStaff");
                    const data = await response.json();

                        console.log(data);

                    if (!response.ok) {
                        alert(`Sikertelen lekérdezés: ${data.message}`);
                    } else {
                        setUsers(data.employees);
                    }
                } catch (err) {
                    console.log(err);
                    alert("Hiba történt a munkatársak lekérése közben.");
                }
            
            fetchEmployees();
    }}, []);
   
    
    return(
        <div className={styles.modalBackground}>
            <div className={styles.modalContainer}>
                    <div className={styles.title}>
                        <h1>Hiba kiosztása</h1>
                    </div>
                        <div className={styles.body}>
                            {employees.length > 0 ? users.map(user =>{
                                return (
                                    <div key={user.id} className={styles.users}>
                                        <input className="form-check-input" type="checkbox" value="" id={`check${user.id}`}/>
                                        <label className="form-check-label" for={`check${user.id}`}> {user.name} </label>
                                    </div>
                                );
                            }) : (<p>Nincs elérhető munkatárs.</p> )}
                        </div>
                    <div className={styles.footer}>
                        <button className={styles.closeBtn} onClick={() => closeAssignTicketModal(false)}>Mégse</button>
                        <button className={styles.saveBtn}>Kiosztás</button>
                    </div>
            </div>
        </div>

           
    )
}

export default AssignTicketModal;
